import requests
import json

class MCPClient:
    def __init__(self, base_url='http://are-sidecar:8000/mcp'):
        self.base_url = base_url
        self.session = requests.Session()
        self.session_id = None

    def _headers(self):
        return {
            'Content-Type': 'application/json',
            'Accept': 'application/json, text/event-stream',
            'mcp-session-id': self.session_id
        }

    def initialize(self):
        payload = {
            "jsonrpc": "2.0",
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "test", "version": "1.0"}
            },
            "id": 1
        }
        r = self.session.post(self.base_url, headers=self._headers(), json=payload)
        self.session_id = r.headers.get('mcp-session-id')
        return r.text

    def call_tool(self, tool_name, arguments=None):
        payload = {
            "jsonrpc": "2.0",
            "method": "tools/call",
            "params": {
                "name": tool_name,
                "arguments": arguments or {}
            },
            "id": 2
        }
        r = self.session.post(self.base_url, headers=self._headers(), json=payload)
        return r.text

    def list_tools(self):
        payload = {
            "jsonrpc": "2.0",
            "method": "tools/list",
            "params": {},
            "id": 3
        }
        r = self.session.post(self.base_url, headers=self._headers(), json=payload)
        return r.text

if __name__ == '__main__':
    client = MCPClient()
    print(client.initialize())
    print('---Tools---')
    print(client.list_tools())
PYEOF

